package kz.structure.reminder;
import android.app.*;import android.os.*;import android.content.*;import android.provider.Settings;import android.net.Uri;import android.graphics.Color;import android.widget.*;import java.util.*;import java.text.*;
public class MainActivity extends Activity {
 LinearLayout layout; EditText partner,guests; Calendar date=Calendar.getInstance(); TextView time;
 TextView label(String s,int size){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(Color.WHITE);t.setPadding(8,12,8,12);layout.addView(t);return t;}
 void base(){ScrollView scroll=new ScrollView(this);layout=new LinearLayout(this);layout.setOrientation(1);layout.setPadding(24,48,24,32);layout.setBackgroundColor(0xff101820);scroll.addView(layout);setContentView(scroll);}
 void button(String s,Runnable r){Button b=new Button(this);b.setText(s);layout.addView(b);b.setOnClickListener(v->r.run());}
 EditText field(String hint){EditText e=new EditText(this);e.setHint(hint);layout.addView(e);return e;}
 String fmt(long t,String f){return new SimpleDateFormat(f,new Locale("ru","RU")).format(new Date(t));}
 public void onCreate(Bundle b){super.onCreate(b);if(getIntent().hasExtra("stage"))showAlarm(getIntent());else home();}
 protected void onNewIntent(Intent i){super.onNewIntent(i);setIntent(i);if(i.hasExtra("stage"))showAlarm(i);else home();}
 void home(){base();label("СОЗДАНИЕ СТРУКТУРЫ",22);label("Напоминания о встречах",28);partner=field("Имя партнёра");guests=field("Гости (по одному на строку)");date=Calendar.getInstance();date.add(Calendar.HOUR,7);time=label(fmt(date.getTimeInMillis(),"dd.MM.yyyy HH:mm"),30);button("Выбрать дату и время",()->new DatePickerDialog(this,(v,y,m,d)->{date.set(y,m,d);new TimePickerDialog(this,(w,h,min)->{date.set(Calendar.HOUR_OF_DAY,h);date.set(Calendar.MINUTE,min);date.set(Calendar.SECOND,0);time.setText(fmt(date.getTimeInMillis(),"dd.MM.yyyy HH:mm"));},date.get(Calendar.HOUR_OF_DAY),date.get(Calendar.MINUTE),true).show();},date.get(Calendar.YEAR),date.get(Calendar.MONTH),date.get(Calendar.DAY_OF_MONTH)).show());button("Разрешения будильника",()->{if(Build.VERSION.SDK_INT>=31&&!getSystemService(AlarmManager.class).canScheduleExactAlarms())startActivity(new Intent(Settings.ACTION_REQUEST_SCHEDULE_EXACT_ALARM,Uri.parse("package:"+getPackageName())));else if(Build.VERSION.SDK_INT>=34&&!getSystemService(NotificationManager.class).canUseFullScreenIntent())startActivity(new Intent(Settings.ACTION_MANAGE_APP_USE_FULL_SCREEN_INTENT,Uri.parse("package:"+getPackageName())));else Toast.makeText(this,"Проверьте разрешение уведомлений",0).show();});button("Сохранить встречу",()->schedule());button("Тест: два коротких через 10 секунд",()->test(6));button("Тест: длинный через 10 секунд",()->test(2));if(Build.VERSION.SDK_INT>=33)requestPermissions(new String[]{"android.permission.POST_NOTIFICATIONS"},1);}
 Intent data(int stage,long meeting,int id){return new Intent(this,AlarmReceiver.class).putExtra("stage",stage).putExtra("meeting",meeting).putExtra("partner",partner.getText().toString()).putExtra("guests",guests.getText().toString()).putExtra("id",id);}
 boolean set(Intent i,long when){AlarmManager a=getSystemService(AlarmManager.class);if(Build.VERSION.SDK_INT>=31&&!a.canScheduleExactAlarms()){Toast.makeText(this,"Разрешите точные будильники",1).show();return false;}PendingIntent p=PendingIntent.getBroadcast(this,i.getIntExtra("id",0),i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);a.setExactAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,when,p);return true;}
 void test(int stage){set(data(stage,System.currentTimeMillis()+10000+stage*3600000L,stage),System.currentTimeMillis()+10000);}
 void schedule(){long m=date.getTimeInMillis();int count=0;for(int s:new int[]{6,2}){long t=m-s*3600000L;if(t>System.currentTimeMillis()&&set(data(s,m,(int)(m/60000)*10+s),t))count++;}Toast.makeText(this,"Запланировано сигналов: "+count,1).show();}
 void showAlarm(Intent i){base();int s=i.getIntExtra("stage",2);label("ДО ВСТРЕЧИ "+(s==6?"6 ЧАСОВ":"2 ЧАСА"),26).setTextColor(s==6?0xff65b7ff:0xffffb34d);long m=i.getLongExtra("meeting",0);label(fmt(m,"HH:mm"),76);label(fmt(m,"dd.MM.yyyy · EEEE"),24);label("ПАРТНЁР",16);label(i.getStringExtra("partner"),30);label("ГОСТИ",16);label(i.getStringExtra("guests"),24);button("Подтвердить",()->{getSystemService(NotificationManager.class).cancel(i.getIntExtra("id",0));finish();});button("Напомнить через 10 минут",()->{Intent n=new Intent(this,AlarmReceiver.class);n.putExtras(i);if(set(n,System.currentTimeMillis()+600000)){getSystemService(NotificationManager.class).cancel(i.getIntExtra("id",0));finish();}});}
}